def get_latest_feed(count=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0349000" if __import__("os").path.isdir("./environment_mix/0349000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _load_logs():
        data = _load("request_logs.json")
        return data if isinstance(data, list) else []

    def _write_log(endpoint, status, user_id=None, error_code=None, meta=None):
        logs = _load_logs()
        row = {
            "id": "rdp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f") + "_" + uuid.uuid4().hex[:8],
            "service": "raindrop",
            "endpoint": endpoint,
            "user_id": user_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, user_id):
        limits = _load("service_limits.json")
        limits = limits if isinstance(limits, list) else []
        cfg = None
        for r in limits:
            if isinstance(r, dict) and r.get("service") == "raindrop":
                cfg = r
                break
        if not isinstance(cfg, dict):
            return None

        window_s = cfg.get("rate_limit_window_seconds", 60)
        max_req = cfg.get("rate_limit_max_requests", None)
        daily_quota = cfg.get("daily_quota_max_requests", None)

        if not (isinstance(window_s, int) and window_s > 0):
            window_s = 60

        logs = _load_logs()
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=window_s)
        today = now.date()

        per_window = 0
        per_day = 0
        for e in logs:
            if not isinstance(e, dict):
                continue
            if e.get("endpoint") != endpoint:
                continue
            if user_id is not None and e.get("user_id") not in (None, user_id):
                continue
            dt = _parse_dt(e.get("timestamp"))
            if not dt:
                continue
            if dt.date() == today:
                per_day += 1
            if dt >= cutoff:
                per_window += 1

        if isinstance(max_req, int) and max_req >= 0 and per_window >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(daily_quota, int) and daily_quota >= 0 and per_day >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _pick_user():
        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        # Ambient auth: select any active user that can serve this call (has at least one active bookmark)
        bookmarks = _load("bookmarks.json")
        bookmarks = bookmarks if isinstance(bookmarks, list) else []
        for u in users:
            if not isinstance(u, dict) or u.get("status") != "active":
                continue
            uid = u.get("id")
            if not isinstance(uid, str):
                continue
            for b in bookmarks:
                if isinstance(b, dict) and b.get("user_id") == uid and b.get("status") == "active":
                    return u
        # Fallback: any active user
        for u in users:
            if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str):
                return u
        return None

    # Validate count
    if count is None:
        count = 20
    if not isinstance(count, int):
        u = _pick_user()
        _write_log("get_latest_feed", "error", user_id=(u.get("id") if u else None), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`count` must be an integer")
    if count < 1 or count > 50:
        u = _pick_user()
        _write_log("get_latest_feed", "error", user_id=(u.get("id") if u else None), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`count` must be between 1 and 50")

    # Cursor: accept vendor cursor OR tolerate arbitrary strings (audit defect: it used a user_id as cursor)
    start_after_created_at = None
    start_after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            u = _pick_user()
            _write_log("get_latest_feed", "error", user_id=(u.get("id") if u else None), error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid `cursor`")
        cur = cursor.strip()
        decoded = None
        # Our cursor format: base64url("v1|<created_at>|<id>")
        try:
            padded = cur + "=" * (-len(cur) % 4)
            decoded = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8", "strict")
        except Exception:
            decoded = None
        if isinstance(decoded, str) and decoded.startswith("v1|"):
            parts = decoded.split("|", 2)
            if len(parts) == 3:
                dt = _parse_dt(parts[1])
                if dt and isinstance(parts[2], str) and parts[2]:
                    start_after_created_at = dt
                    start_after_id = parts[2]
        # If not decodable, treat as "no cursor" rather than rejecting.

    user = _pick_user()
    if not user:
        _write_log("get_latest_feed", "error", user_id=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized")

    uid = user.get("id")

    limit_err = _enforce_limits("get_latest_feed", uid)
    if limit_err:
        _write_log("get_latest_feed", "error", user_id=uid, error_code=limit_err["error"]["code"])
        return limit_err

    bookmarks = _load("bookmarks.json")
    bookmarks = bookmarks if isinstance(bookmarks, list) else []

    active = []
    for b in bookmarks:
        if not isinstance(b, dict):
            continue
        if b.get("user_id") != uid:
            continue
        if b.get("status") != "active":
            continue
        dt = _parse_dt(b.get("created_at")) or _parse_dt(b.get("updated_at"))
        if not dt:
            dt = datetime.datetime(1970, 1, 1)
        active.append((dt, str(b.get("id", "")), b))

    # Sort by created_at desc, stable by id desc
    active.sort(key=lambda x: (x[0], x[1]), reverse=True)

    # Apply cursor if we have one (start strictly after the cursor item)
    start_index = 0
    if start_after_created_at is not None:
        for i, (dt, bid, _) in enumerate(active):
            if dt < start_after_created_at:
                start_index = i
                break
            if dt == start_after_created_at and start_after_id is not None and bid < start_after_id:
                start_index = i
                break
        else:
            start_index = len(active)

    page = [row for _, _, row in active[start_index:start_index + count]]
    has_more = (start_index + count) < len(active)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _parse_dt(last.get("created_at")) or _parse_dt(last.get("updated_at")) or datetime.datetime(1970, 1, 1)
        payload = "v1|%s|%s" % (last_dt.replace(microsecond=0).isoformat() + "Z", last.get("id"))
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    _write_log("get_latest_feed", "ok", user_id=uid, error_code=None, meta={"returned": len(page), "has_more": has_more})
    return {"items": page, "count": len(page), "total": len(active), "has_more": has_more, "next_cursor": next_cursor}

def add_bookmark(url, title=None, description=None, tags=None, collection_id=None, **_extra):
    import json, os, datetime, time, re, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0349000" if __import__("os").path.isdir("./environment_mix/0349000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _audit(endpoint, status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - start) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": now,
            }
        )
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        tnow = datetime.datetime.utcnow()
        window_s = 60
        max_per_window = 60
        max_per_day = 2000
        recent = 0
        today = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (tnow - dt).total_seconds() <= window_s:
                if r.get("endpoint") == endpoint:
                    recent += 1
            if dt.date() == tnow.date():
                if r.get("endpoint") == endpoint:
                    today += 1
        if recent >= max_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if today >= max_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    limit_err = _enforce_limits("add_bookmark")
    if limit_err:
        _audit("add_bookmark", 429, error_code=limit_err["error"]["code"])
        return limit_err

    # Validate url
    if not isinstance(url, str) or not url.strip():
        _audit("add_bookmark", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`url` must be a non-empty string")
    url = url.strip()
    if len(url) < 1 or len(url) > 4096:
        _audit("add_bookmark", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`url` length must be between 1 and 4096")

    # basic URL sanity
    try:
        parsed = urllib.parse.urlparse(url)
    except Exception:
        parsed = None
    if not parsed or not parsed.scheme or not parsed.netloc:
        _audit("add_bookmark", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`url` must be an absolute URL with scheme and host")

    if title is not None and not isinstance(title, str):
        _audit("add_bookmark", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`title` must be a string")
    if description is not None and not isinstance(description, str):
        _audit("add_bookmark", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`description` must be a string or null")

    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(t, str)) for t in tags):
            _audit("add_bookmark", 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`tags` must be an array of strings")

    if collection_id is None:
        collection_id = "0"
    if not isinstance(collection_id, str):
        _audit("add_bookmark", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`collection_id` must be a string")
    if not re.match(r"^(0|rdp_col_01H[0-9A-Za-z]{20})$", collection_id):
        _audit("add_bookmark", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`collection_id` format is invalid")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active":
            user = u
            break
    if not user:
        _audit("add_bookmark", 401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authenticated")

    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []

    # Resolve collection
    target_collection = None
    if collection_id == "0":
        for c in collections:
            if not isinstance(c, dict):
                continue
            if c.get("user_id") == user.get("id") and c.get("is_system") is True and c.get("slug") == "unsorted" and c.get("status") == "active":
                target_collection = c
                break
        if not target_collection:
            _audit("add_bookmark", 404, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Unsorted collection not found for user")
    else:
        for c in collections:
            if not isinstance(c, dict):
                continue
            if c.get("id") == collection_id and c.get("status") == "active" and c.get("user_id") == user.get("id"):
                target_collection = c
                break
        if not target_collection:
            _audit("add_bookmark", 404, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Collection not found")

    bookmarks = _load("bookmarks.json")
    if not isinstance(bookmarks, list):
        bookmarks = []

    # Idempotency-ish: unique(user_id,url) where status != deleted
    existing = None
    for b in bookmarks:
        if not isinstance(b, dict):
            continue
        if b.get("user_id") == user.get("id") and b.get("url") == url and b.get("status") != "deleted":
            existing = b
            break
    if existing:
        # Ensure it is not associated with wrong collection owner (shouldn't happen if store valid)
        _audit("add_bookmark", 200)
        return {"bookmark": existing, "created": False}

    # Title derivation (offline): use provided title, else fallback to URL
    final_title = title.strip() if isinstance(title, str) and title.strip() else None
    if not final_title:
        # Attempt "derive" from URL: use host + path basename as a weak metadata substitute; fallback to url.
        base = parsed.path.rstrip("/").split("/")[-1]
        if base:
            final_title = base
        else:
            final_title = parsed.netloc or url
        if not final_title:
            final_title = url

    domain = parsed.netloc.lower() if parsed and parsed.netloc else None

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex[:24]

    bm = {
        "id": _new_id("rdp_bmk_"),
        "user_id": user.get("id"),
        "collection_id": target_collection.get("id"),
        "url": url,
        "title": final_title,
        "description": description if description is not None else None,
        "content_text": None,
        "domain": domain,
        "created_at": now,
        "updated_at": now,
        "status": "active",
        "source": "api",
    }

    # Persist bookmark first
    bookmarks.append(bm)
    _save("bookmarks.json", bookmarks)

    # Tags upsert + edges
    if tags:
        tags_rows = _load("tags.json")
        if not isinstance(tags_rows, list):
            tags_rows = []
        edges = _load("bookmark_tags.json")
        if not isinstance(edges, list):
            edges = []

        def _norm_tag(t):
            # case-fold + trim + collapse whitespace
            t2 = t.strip().casefold()
            t2 = re.sub(r"\s+", " ", t2)
            return t2

        # build index
        by_user_name = {}
        for tr in tags_rows:
            if not isinstance(tr, dict):
                continue
            if tr.get("status") == "deleted":
                continue
            key = (tr.get("user_id"), tr.get("name"))
            by_user_name[key] = tr

        # existing edges set
        edge_set = set()
        for e in edges:
            if not isinstance(e, dict):
                continue
            edge_set.add((e.get("bookmark_id"), e.get("tag_id")))

        changed_tags = False
        changed_edges = False
        for t in tags:
            if not isinstance(t, str):
                continue
            nt = _norm_tag(t)
            if not nt:
                continue
            if len(nt) < 1 or len(nt) > 64:
                # For add_bookmark, treat invalid tag length as validation error
                _audit("add_bookmark", 400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Each tag name must be between 1 and 64 characters after normalization")
            key = (user.get("id"), nt)
            tr = by_user_name.get(key)
            if tr is None:
                tr = {
                    "id": _new_id("rdp_tag_"),
                    "user_id": user.get("id"),
                    "name": nt,
                    "created_at": now,
                    "updated_at": now,
                    "status": "active",
                }
                tags_rows.append(tr)
                by_user_name[key] = tr
                changed_tags = True
            else:
                # if merged, keep as-is; only active/merged allowed, but association should be with active tags per rules
                if tr.get("status") != "active":
                    # revive if possible? lifecycle doesn't allow merged->active, so create a new active tag with new name variant not possible.
                    # We'll refuse because rule says upsert in status='active'
                    _audit("add_bookmark", 409, error_code="CONFLICT")
                    return _err("CONFLICT", "Tag exists but is not active", tag=nt, status=tr.get("status"))

            if (bm["id"], tr["id"]) not in edge_set:
                edges.append(
                    {
                        "id": _new_id("rdp_bmt_"),
                        "bookmark_id": bm["id"],
                        "tag_id": tr["id"],
                        "user_id": user.get("id"),
                        "created_at": now,
                    }
                )
                edge_set.add((bm["id"], tr["id"]))
                changed_edges = True

        if changed_tags:
            _save("tags.json", tags_rows)
        if changed_edges:
            _save("bookmark_tags.json", edges)

    _audit("add_bookmark", 201)
    return {"bookmark": bm, "created": True}

def search_by_tag(tag, collection_id=None, count=None, from_date=None, to_date=None, cursor=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0349000" if __import__("os").path.isdir("./environment_mix/0349000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(endpoint, status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - start) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": now,
            }
        )
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        tnow = datetime.datetime.utcnow()
        window_s = 60
        max_per_window = 120
        max_per_day = 5000
        recent = 0
        today = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (tnow - dt).total_seconds() <= window_s:
                if r.get("endpoint") == endpoint:
                    recent += 1
            if dt.date() == tnow.date():
                if r.get("endpoint") == endpoint:
                    today += 1
        if recent >= max_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if today >= max_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    limit_err = _enforce_limits("search_by_tag")
    if limit_err:
        _audit("search_by_tag", 429, error_code=limit_err["error"]["code"])
        return limit_err

    if not isinstance(tag, str) or not tag.strip():
        _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`tag` must be a non-empty string")

    if count is None:
        count = 10
    if not isinstance(count, int):
        _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`count` must be an integer")
    if count < 1 or count > 50:
        _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`count` must be between 1 and 50")

    if collection_id is None:
        collection_id = "0"
    if not isinstance(collection_id, str) or not re.match(r"^(0|rdp_col_01H[0-9A-Za-z]{20})$", collection_id):
        _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`collection_id` format is invalid")

    if cursor is not None and not isinstance(cursor, str):
        _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`cursor` must be a string")

    def _parse_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", s):
            return ("err", _err("VALIDATION_ERROR", f"`{field}` must be in YYYY-MM-DD format"))
        try:
            return datetime.date.fromisoformat(s)
        except Exception:
            return ("err", _err("VALIDATION_ERROR", f"`{field}` must be a valid date"))
    fd = _parse_date(from_date, "from_date")
    if isinstance(fd, tuple) and fd[0] == "err":
        _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
        return fd[1]
    td = _parse_date(to_date, "to_date")
    if isinstance(td, tuple) and td[0] == "err":
        _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
        return td[1]
    if fd and td and fd > td:
        _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`from_date` must be <= `to_date`")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active":
            user = u
            break
    if not user:
        _audit("search_by_tag", 401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authenticated")

    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []
    col_by_id = {c.get("id"): c for c in collections if isinstance(c, dict) and c.get("status") != "deleted"}

    # Determine allowed collection scope
    allowed_collection_ids = None
    if collection_id == "0":
        allowed_collection_ids = set(
            c.get("id") for c in collections if isinstance(c, dict) and c.get("user_id") == user.get("id") and c.get("status") == "active"
        )
    else:
        c = col_by_id.get(collection_id)
        if not c or c.get("user_id") != user.get("id") or c.get("status") != "active":
            _audit("search_by_tag", 404, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Collection not found")
        allowed_collection_ids = {collection_id}

    def _norm_tag(t):
        t2 = t.strip().casefold()
        t2 = re.sub(r"\s+", " ", t2)
        return t2

    nt = _norm_tag(tag)
    if not nt:
        _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`tag` must be non-empty after normalization")

    tags_rows = _load("tags.json")
    if not isinstance(tags_rows, list):
        tags_rows = []

    tag_row = None
    for tr in tags_rows:
        if not isinstance(tr, dict):
            continue
        if tr.get("user_id") != user.get("id"):
            continue
        if tr.get("status") == "deleted":
            continue
        if tr.get("name") == nt:
            tag_row = tr
            break

    # If tag not found, return empty set
    if not tag_row:
        _audit("search_by_tag", 200)
        return {"items": [], "count": 0, "total": 0, "has_more": False, "cursor": None}

    edges = _load("bookmark_tags.json")
    if not isinstance(edges, list):
        edges = []
    bookmarks = _load("bookmarks.json")
    if not isinstance(bookmarks, list):
        bookmarks = []

    bm_by_id = {b.get("id"): b for b in bookmarks if isinstance(b, dict)}
    matched = []
    for e in edges:
        if not isinstance(e, dict):
            continue
        if e.get("user_id") != user.get("id"):
            continue
        if e.get("tag_id") != tag_row.get("id"):
            continue
        b = bm_by_id.get(e.get("bookmark_id"))
        if not b or b.get("user_id") != user.get("id"):
            continue
        if b.get("status") != "active":
            continue
        if b.get("collection_id") not in allowed_collection_ids:
            continue
        # date filters on created_at (date portion)
        ca = b.get("created_at")
        if isinstance(ca, str):
            try:
                cadt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
                cad = cadt.date()
            except Exception:
                cad = None
        else:
            cad = None
        if fd and cad and cad < fd:
            continue
        if td and cad and cad > td:
            continue
        # If date can't be parsed, include (no explicit rule), but keep deterministic ordering by treating as oldest
        matched.append(b)

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    # order by created_at desc
    matched.sort(key=lambda r: (_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)

    # cursor = base64 offset
    offset = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            m = re.match(r"^offset:(\d+)$", decoded)
            if not m:
                raise ValueError("bad cursor")
            offset = int(m.group(1))
            if offset < 0:
                raise ValueError("bad cursor")
        except Exception:
            _audit("search_by_tag", 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid `cursor`")

    page = matched[offset : offset + count]
    next_offset = offset + len(page)
    has_more = next_offset < len(matched)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    _audit("search_by_tag", 200)
    return {
        "items": page,
        "count": len(page),
        "total": len(matched),
        "has_more": has_more,
        "cursor": next_cursor,
    }

def search_bookmarks(query, collection_id=None, count=None, from_date=None, to_date=None, cursor=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0349000" if __import__("os").path.isdir("./environment_mix/0349000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(endpoint, status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - start) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": now,
            }
        )
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        tnow = datetime.datetime.utcnow()
        window_s = 60
        max_per_window = 120
        max_per_day = 5000
        recent = 0
        today = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (tnow - dt).total_seconds() <= window_s:
                if r.get("endpoint") == endpoint:
                    recent += 1
            if dt.date() == tnow.date():
                if r.get("endpoint") == endpoint:
                    today += 1
        if recent >= max_per_window:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if today >= max_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    limit_err = _enforce_limits("search_bookmarks")
    if limit_err:
        _audit("search_bookmarks", 429, error_code=limit_err["error"]["code"])
        return limit_err

    if not isinstance(query, str) or not query.strip():
        _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`query` must be a non-empty string")

    if count is None:
        count = 10
    if not isinstance(count, int):
        _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`count` must be an integer")
    if count < 1 or count > 50:
        _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`count` must be between 1 and 50")

    if collection_id is None:
        collection_id = "0"
    if not isinstance(collection_id, str) or not re.match(r"^(0|rdp_col_01H[0-9A-Za-z]{20})$", collection_id):
        _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`collection_id` format is invalid")

    if cursor is not None and not isinstance(cursor, str):
        _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`cursor` must be a string")

    def _parse_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", s):
            return ("err", _err("VALIDATION_ERROR", f"`{field}` must be in YYYY-MM-DD format"))
        try:
            return datetime.date.fromisoformat(s)
        except Exception:
            return ("err", _err("VALIDATION_ERROR", f"`{field}` must be a valid date"))

    fd = _parse_date(from_date, "from_date")
    if isinstance(fd, tuple) and fd[0] == "err":
        _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
        return fd[1]
    td = _parse_date(to_date, "to_date")
    if isinstance(td, tuple) and td[0] == "err":
        _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
        return td[1]
    if fd and td and fd > td:
        _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`from_date` must be <= `to_date`")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active":
            user = u
            break
    if not user:
        _audit("search_bookmarks", 401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authenticated")

    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []
    col_by_id = {c.get("id"): c for c in collections if isinstance(c, dict) and c.get("status") != "deleted"}

    # Determine allowed collection scope
    if collection_id == "0":
        allowed_collection_ids = set(
            c.get("id") for c in collections if isinstance(c, dict) and c.get("user_id") == user.get("id") and c.get("status") == "active"
        )
    else:
        c = col_by_id.get(collection_id)
        if not c or c.get("user_id") != user.get("id") or c.get("status") != "active":
            _audit("search_bookmarks", 404, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Collection not found")
        allowed_collection_ids = {collection_id}

    bookmarks = _load("bookmarks.json")
    if not isinstance(bookmarks, list):
        bookmarks = []

    q = query.strip().casefold()
    # Tokenize query for scoring
    tokens = [t for t in re.split(r"\s+", q) if t]
    if not tokens:
        _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`query` must contain searchable terms")

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    results = []
    for b in bookmarks:
        if not isinstance(b, dict):
            continue
        if b.get("user_id") != user.get("id"):
            continue
        if b.get("status") != "active":
            continue
        if b.get("collection_id") not in allowed_collection_ids:
            continue

        ca = b.get("created_at")
        cadt = _dt(ca)
        cad = cadt.date() if cadt else None
        if fd and cad and cad < fd:
            continue
        if td and cad and cad > td:
            continue

        hay = " ".join(
            [
                (b.get("title") or ""),
                (b.get("description") or ""),
                (b.get("content_text") or ""),
            ]
        ).casefold()

        # Simple full-text matching: require at least one token match
        score = 0
        for t in tokens:
            if t in hay:
                score += 1
        if score <= 0:
            continue
        results.append((score, b))

    # Order by relevance (score desc) then created_at desc
    results.sort(
        key=lambda sb: (
            sb[0],
            (_dt(sb[1].get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)),
        ),
        reverse=True,
    )

    # Cursor = base64 offset in this ordered list
    offset = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            m = re.match(r"^offset:(\d+)$", decoded)
            if not m:
                raise ValueError("bad cursor")
            offset = int(m.group(1))
            if offset < 0:
                raise ValueError("bad cursor")
        except Exception:
            _audit("search_bookmarks", 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid `cursor`")

    ordered = [b for _, b in results]
    page = ordered[offset : offset + count]
    next_offset = offset + len(page)
    has_more = next_offset < len(ordered)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    _audit("search_bookmarks", 200)
    return {
        "items": page,
        "count": len(page),
        "total": len(ordered),
        "has_more": has_more,
        "cursor": next_cursor,
    }

def get_current_user(include_scopes=None, include_limits=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0349000" if __import__("os").path.isdir("./environment_mix/0349000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _get_reqlog_filename():
        # Choose an existing request log file if present, else default.
        candidates = [
            "request_logs.json",
            "requests.json",
            "usage.json",
            "audit.json",
            "audit_logs.json",
            "api_logs.json",
            "request_log.json",
        ]
        for c in candidates:
            if os.path.exists(os.path.join(_DB, c)):
                return c
        return "request_logs.json"

    def _load_reqlog():
        fn = _get_reqlog_filename()
        data = _load(fn)
        if not isinstance(data, list):
            data = []
        return fn, data

    def _log_call(endpoint, user_id, status, latency_ms, meta=None):
        fn, logs = _load_reqlog()
        row = {
            "id": "rdp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "user_id": user_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_state(user_id):
        # Simple per-user rate limit: 120 requests/minute; daily quota: 5000/day.
        logs_fn, logs = _load_reqlog()
        now = datetime.datetime.utcnow()
        win_start = now - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now.year, now.month, now.day)

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("user_id") != user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= win_start:
                per_min += 1
            if ts >= day_start:
                per_day += 1

        limit_per_min = 120
        quota_per_day = 5000

        reset_min = (now.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1))
        reset_day = (day_start + datetime.timedelta(days=1))

        return {
            "rate_limit": limit_per_min,
            "rate_remaining": max(0, limit_per_min - per_min),
            "rate_reset": reset_min.replace(microsecond=0).isoformat() + "Z",
            "quota_limit": quota_per_day,
            "quota_remaining": max(0, quota_per_day - per_day),
            "quota_reset": reset_day.replace(microsecond=0).isoformat() + "Z",
            "observed": {"requests_last_minute": per_min, "requests_today": per_day},
            "logs_file": logs_fn,
        }

    t0 = time.time()

    # Validate inputs
    if include_scopes is not None and not isinstance(include_scopes, bool):
        return _err("VALIDATION_ERROR", "include_scopes must be a boolean")
    if include_limits is not None and not isinstance(include_limits, bool):
        return _err("VALIDATION_ERROR", "include_limits must be a boolean")

    # Ambient auth: resolve an active user that can serve the call.
    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    authed_user = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active":
            authed_user = u
            break
    if authed_user is None:
        # No valid token context can be resolved from store
        latency = (time.time() - t0) * 1000
        _log_call("get_current_user", None, 401, latency, meta={"reason": "no_active_user"})
        return _err("UNAUTHORIZED", "Missing/invalid access token")

    # Rate-limit enforcement (based on request logs)
    state = _rate_state(authed_user.get("id"))
    if state["rate_remaining"] <= 0:
        latency = (time.time() - t0) * 1000
        _log_call("get_current_user", authed_user.get("id"), 429, latency, meta={"type": "rate_limit"})
        return _err(
            "RATE_LIMIT",
            "Rate limit exceeded",
            limit=state["rate_limit"],
            reset_at=state["rate_reset"],
        )
    if state["quota_remaining"] <= 0:
        latency = (time.time() - t0) * 1000
        _log_call("get_current_user", authed_user.get("id"), 429, latency, meta={"type": "quota"})
        return _err(
            "QUOTA_EXCEEDED",
            "Daily quota exceeded",
            quota=state["quota_limit"],
            reset_at=state["quota_reset"],
        )

    body = {
        "user": {
            "id": authed_user.get("id"),
            "email": authed_user.get("email"),
            "display_name": authed_user.get("display_name"),
            "status": authed_user.get("status"),
            "default_collection_id": authed_user.get("default_collection_id", None),
            "created_at": authed_user.get("created_at"),
            "updated_at": authed_user.get("updated_at"),
        }
    }

    if include_scopes:
        # No explicit token model in datastore; expose effective baseline scopes.
        body["scopes"] = ["user.read", "collections.read", "collections.write", "bookmarks.read", "bookmarks.write", "tags.write"]

    if include_limits:
        body["limits"] = {
            "rate": {
                "limit": state["rate_limit"],
                "remaining": state["rate_remaining"] - 1,  # account for this call
                "reset_at": state["rate_reset"],
            },
            "quota": {
                "limit": state["quota_limit"],
                "remaining": state["quota_remaining"] - 1,  # account for this call
                "reset_at": state["quota_reset"],
            },
        }

    latency = (time.time() - t0) * 1000
    _log_call("get_current_user", authed_user.get("id"), 200, latency)
    return body

def list_collections(status=None, count=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0349000" if __import__("os").path.isdir("./environment_mix/0349000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _load_logs():
        data = _load("request_logs.json")
        return data if isinstance(data, list) else []

    def _write_log(endpoint, status_s, user_id=None, error_code=None, meta=None):
        logs = _load_logs()
        row = {
            "id": "rdp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f") + "_" + uuid.uuid4().hex[:8],
            "service": "raindrop",
            "endpoint": endpoint,
            "user_id": user_id,
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, user_id):
        limits = _load("service_limits.json")
        limits = limits if isinstance(limits, list) else []
        cfg = None
        for r in limits:
            if isinstance(r, dict) and r.get("service") == "raindrop":
                cfg = r
                break
        if not isinstance(cfg, dict):
            return None

        window_s = cfg.get("rate_limit_window_seconds", 60)
        max_req = cfg.get("rate_limit_max_requests", None)
        daily_quota = cfg.get("daily_quota_max_requests", None)

        if not (isinstance(window_s, int) and window_s > 0):
            window_s = 60

        logs = _load_logs()
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=window_s)
        today = now.date()

        per_window = 0
        per_day = 0
        for e in logs:
            if not isinstance(e, dict):
                continue
            if e.get("endpoint") != endpoint:
                continue
            if user_id is not None and e.get("user_id") not in (None, user_id):
                continue
            dt = _parse_dt(e.get("timestamp"))
            if not dt:
                continue
            if dt.date() == today:
                per_day += 1
            if dt >= cutoff:
                per_window += 1

        if isinstance(max_req, int) and max_req >= 0 and per_window >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(daily_quota, int) and daily_quota >= 0 and per_day >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _pick_user():
        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        cols = _load("collections.json")
        cols = cols if isinstance(cols, list) else []
        for u in users:
            if not isinstance(u, dict) or u.get("status") != "active":
                continue
            uid = u.get("id")
            if not isinstance(uid, str):
                continue
            for c in cols:
                if isinstance(c, dict) and c.get("user_id") == uid and c.get("status") in ("active", "archived"):
                    return u
        for u in users:
            if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str):
                return u
        return None

    # Validate status
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            u = _pick_user()
            _write_log("list_collections", "error", user_id=(u.get("id") if u else None), error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`status` must be one of: active, archived")

    # Validate count
    if count is None:
        count = 20
    if not isinstance(count, int):
        u = _pick_user()
        _write_log("list_collections", "error", user_id=(u.get("id") if u else None), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`count` must be an integer")
    if count < 1 or count > 50:
        u = _pick_user()
        _write_log("list_collections", "error", user_id=(u.get("id") if u else None), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`count` must be between 1 and 50")

    # Cursor: accept base64 cursor; tolerate arbitrary strings (audit defect used user_id)
    start_after_updated_at = None
    start_after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            u = _pick_user()
            _write_log("list_collections", "error", user_id=(u.get("id") if u else None), error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        cur = cursor.strip()
        decoded = None
        try:
            padded = cur + "=" * (-len(cur) % 4)
            decoded = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8", "strict")
        except Exception:
            decoded = None
        if isinstance(decoded, str) and decoded.startswith("v1|"):
            parts = decoded.split("|", 2)
            if len(parts) == 3:
                dt = _parse_dt(parts[1])
                if dt and isinstance(parts[2], str) and parts[2]:
                    start_after_updated_at = dt
                    start_after_id = parts[2]
        # If not decodable, treat as "no cursor" rather than rejecting.

    user = _pick_user()
    if not user:
        _write_log("list_collections", "error", user_id=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized")

    uid = user.get("id")

    limit_err = _enforce_limits("list_collections", uid)
    if limit_err:
        _write_log("list_collections", "error", user_id=uid, error_code=limit_err["error"]["code"])
        return limit_err

    collections = _load("collections.json")
    collections = collections if isinstance(collections, list) else []

    rows = []
    for c in collections:
        if not isinstance(c, dict):
            continue
        if c.get("user_id") != uid:
            continue
        if c.get("status") == "deleted":
            continue
        if status is not None and c.get("status") != status:
            continue
        dt = _parse_dt(c.get("updated_at")) or _parse_dt(c.get("created_at"))
        if not dt:
            dt = datetime.datetime(1970, 1, 1)
        rows.append((dt, str(c.get("id", "")), c))

    rows.sort(key=lambda x: (x[0], x[1]), reverse=True)

    start_index = 0
    if start_after_updated_at is not None:
        for i, (dt, cid, _) in enumerate(rows):
            if dt < start_after_updated_at:
                start_index = i
                break
            if dt == start_after_updated_at and start_after_id is not None and cid < start_after_id:
                start_index = i
                break
        else:
            start_index = len(rows)

    page = [r for _, _, r in rows[start_index:start_index + count]]
    has_more = (start_index + count) < len(rows)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _parse_dt(last.get("updated_at")) or _parse_dt(last.get("created_at")) or datetime.datetime(1970, 1, 1)
        payload = "v1|%s|%s" % (last_dt.replace(microsecond=0).isoformat() + "Z", last.get("id"))
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    _write_log("list_collections", "ok", user_id=uid, meta={"returned": len(page), "has_more": has_more})
    return {"items": page, "count": len(page), "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

def create_collection(title, slug=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0349000" if __import__("os").path.isdir("./environment_mix/0349000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _get_reqlog_filename():
        candidates = [
            "request_logs.json",
            "requests.json",
            "usage.json",
            "audit.json",
            "audit_logs.json",
            "api_logs.json",
            "request_log.json",
        ]
        for c in candidates:
            if os.path.exists(os.path.join(_DB, c)):
                return c
        return "request_logs.json"

    def _load_reqlog():
        fn = _get_reqlog_filename()
        data = _load(fn)
        if not isinstance(data, list):
            data = []
        return fn, data

    def _log_call(endpoint, user_id, status_code, latency_ms, meta=None):
        fn, logs = _load_reqlog()
        row = {
            "id": "rdp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "user_id": user_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_state(user_id):
        fn, logs = _load_reqlog()
        now = datetime.datetime.utcnow()
        win_start = now - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now.year, now.month, now.day)

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("user_id") != user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= win_start:
                per_min += 1
            if ts >= day_start:
                per_day += 1

        limit_per_min = 120
        quota_per_day = 5000

        reset_min = (now.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1))
        reset_day = (day_start + datetime.timedelta(days=1))
        return {
            "rate_limit": limit_per_min,
            "rate_remaining": max(0, limit_per_min - per_min),
            "rate_reset": reset_min.replace(microsecond=0).isoformat() + "Z",
            "quota_limit": quota_per_day,
            "quota_remaining": max(0, quota_per_day - per_day),
            "quota_reset": reset_day.replace(microsecond=0).isoformat() + "Z",
            "logs_file": fn,
        }

    def _slugify(s):
        s = s.strip().lower()
        s = re.sub(r"[^a-z0-9]+", "-", s)
        s = re.sub(r"-{2,}", "-", s).strip("-")
        return s or "collection"

    def _gen_id():
        # Format: rdp_col_01H + 20 base62 chars
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        import random
        rand = "".join(random.choice(alphabet) for _ in range(20))
        return "rdp_col_01H" + rand

    t0 = time.time()

    # Validate inputs
    if not isinstance(title, str) or len(title.strip()) < 1:
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
    title_clean = title.strip()

    if slug is not None:
        if not isinstance(slug, str):
            return _err("VALIDATION_ERROR", "slug must be a string")
        if not re.fullmatch(r"^[a-z0-9]+(?:-[a-z0-9]+)*$", slug):
            return _err("VALIDATION_ERROR", "slug must match ^[a-z0-9]+(?:-[a-z0-9]+)*$")
        slug_clean = slug
    else:
        slug_clean = _slugify(title_clean)

    # Ambient auth
    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    authed_user = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active":
            authed_user = u
            break
    if authed_user is None:
        latency = (time.time() - t0) * 1000
        _log_call("create_collection", None, 401, latency, meta={"reason": "no_active_user"})
        return _err("UNAUTHORIZED", "Missing/invalid access token")

    # Rate-limit enforcement
    state = _rate_state(authed_user.get("id"))
    if state["rate_remaining"] <= 0:
        latency = (time.time() - t0) * 1000
        _log_call("create_collection", authed_user.get("id"), 429, latency, meta={"type": "rate_limit"})
        return _err("RATE_LIMIT", "Rate limit exceeded", limit=state["rate_limit"], reset_at=state["rate_reset"])
    if state["quota_remaining"] <= 0:
        latency = (time.time() - t0) * 1000
        _log_call("create_collection", authed_user.get("id"), 429, latency, meta={"type": "quota"})
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=state["quota_limit"], reset_at=state["quota_reset"])

    cols = _load("collections.json")
    if not isinstance(cols, list):
        cols = []

    # Enforce uniqueness constraints per user:
    # unique(user_id, slug)
    for c in cols:
        if not isinstance(c, dict):
            continue
        if c.get("user_id") != authed_user.get("id"):
            continue
        if c.get("slug") == slug_clean:
            # even if deleted? schema says unique(user_id, slug) (no exception)
            latency = (time.time() - t0) * 1000
            _log_call("create_collection", authed_user.get("id"), 409, latency, meta={"conflict": "slug"})
            return _err("CONFLICT", "Collection slug already exists for this user", field="slug")

    # unique(user_id, title) where status != 'deleted'
    for c in cols:
        if not isinstance(c, dict):
            continue
        if c.get("user_id") != authed_user.get("id"):
            continue
        if c.get("status") != "deleted" and c.get("title") == title_clean:
            latency = (time.time() - t0) * 1000
            _log_call("create_collection", authed_user.get("id"), 409, latency, meta={"conflict": "title"})
            return _err("CONFLICT", "Collection title already exists for this user", field="title")

    new_id = _gen_id()
    now = _now_iso()
    row = {
        "id": new_id,
        "user_id": authed_user.get("id"),
        "title": title_clean,
        "slug": slug_clean,
        "is_system": False,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    cols.append(row)
    _save("collections.json", cols)

    latency = (time.time() - t0) * 1000
    _log_call("create_collection", authed_user.get("id"), 201, latency, meta={"collection_id": new_id})

    return {"collection": row}

def update_collection(id, title=None, slug=None, status=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0349000" if __import__("os").path.isdir("./environment_mix/0349000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _load_logs():
        data = _load("request_logs.json")
        return data if isinstance(data, list) else []

    def _write_log(endpoint, status_s, user_id=None, error_code=None, meta=None):
        logs = _load_logs()
        row = {
            "id": "rdp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f") + "_" + uuid.uuid4().hex[:8],
            "service": "raindrop",
            "endpoint": endpoint,
            "user_id": user_id,
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(user_id):
        cfgs = _load("service_limits.json")
        cfgs = cfgs if isinstance(cfgs, list) else []
        cfg = None
        for r in cfgs:
            if isinstance(r, dict) and r.get("service") == "raindrop":
                cfg = r
                break
        if not isinstance(cfg, dict) or not user_id:
            return None

        window_s = cfg.get("rate_limit_window_seconds", 60)
        max_req = cfg.get("rate_limit_max_requests", None)
        daily_quota = cfg.get("daily_quota_max_requests", None)
        if not (isinstance(window_s, int) and window_s > 0):
            window_s = 60

        logs = _load_logs()
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=window_s)
        day_start = datetime.datetime(now.year, now.month, now.day)

        in_window = 0
        in_day = 0
        for row in logs:
            if not isinstance(row, dict):
                continue
            if row.get("service") != "raindrop":
                continue
            if row.get("user_id") != user_id:
                continue
            ts = row.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
            except Exception:
                continue
            if dt >= window_start:
                in_window += 1
            if dt >= day_start:
                in_day += 1

        if isinstance(max_req, int) and max_req >= 0 and in_window >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(daily_quota, int) and daily_quota >= 0 and in_day >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    endpoint = "update_collection"

    # Validate inputs
    if not isinstance(id, str) or not re.match(r"^rdp_col_01H[0-9A-Za-z]{20}$", id):
        _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "id"})
        return _err("VALIDATION_ERROR", "Invalid id format", field="id")
    if title is not None:
        if not isinstance(title, str) or len(title.strip()) < 1:
            _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "title"})
            return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")
        title = title.strip()
    if slug is not None:
        if not isinstance(slug, str) or not re.match(r"^[a-z0-9]+(?:-[a-z0-9]+)*$", slug):
            _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "slug"})
            return _err("VALIDATION_ERROR", "Invalid slug format", field="slug")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status")

    collections = _load("collections.json")
    collections = collections if isinstance(collections, list) else []
    users = _load("users.json")
    users = users if isinstance(users, list) else []

    # Find target collection
    col = None
    for r in collections:
        if isinstance(r, dict) and r.get("id") == id:
            col = r
            break
    if not isinstance(col, dict) or col.get("status") == "deleted":
        _write_log(endpoint, "error", None, "NOT_FOUND", {"id": id})
        return _err("NOT_FOUND", "Collection not found")

    # Ambient auth: choose authenticated user that owns the collection and is active
    user_id = col.get("user_id")
    authed_user = None
    if isinstance(user_id, str):
        for u in users:
            if isinstance(u, dict) and u.get("id") == user_id and u.get("status") == "active":
                authed_user = u
                break
    if not authed_user:
        _write_log(endpoint, "error", user_id if isinstance(user_id, str) else None, "UNAUTHORIZED", {"id": id})
        return _err("UNAUTHORIZED", "Not authorized to update this collection")

    lim = _enforce_limits(authed_user.get("id"))
    if lim:
        _write_log(endpoint, "error", authed_user.get("id"), lim["error"]["code"])
        return lim

    # System collection rules: only 'unsorted' allowed and should not be mutated except status transitions? enforce minimal: cannot change slug/title
    if col.get("is_system") is True:
        if title is not None or slug is not None:
            _write_log(endpoint, "error", authed_user.get("id"), "VALIDATION_ERROR", {"rule": "system_collection_immutable"})
            return _err("VALIDATION_ERROR", "System collections cannot change title/slug", rule="system collections are immutable (except status)")

    # Enforce uniqueness constraints for title and slug per user (excluding deleted rows)
    if slug is not None and slug != col.get("slug"):
        for r in collections:
            if not isinstance(r, dict):
                continue
            if r.get("user_id") != authed_user.get("id"):
                continue
            if r.get("status") == "deleted":
                continue
            if r.get("slug") == slug:
                _write_log(endpoint, "error", authed_user.get("id"), "CONFLICT", {"field": "slug"})
                return _err("CONFLICT", "slug must be unique per user", field="slug")
    if title is not None and title != col.get("title"):
        for r in collections:
            if not isinstance(r, dict):
                continue
            if r.get("user_id") != authed_user.get("id"):
                continue
            if r.get("status") == "deleted":
                continue
            if r.get("title") == title:
                _write_log(endpoint, "error", authed_user.get("id"), "CONFLICT", {"field": "title"})
                return _err("CONFLICT", "title must be unique per user (excluding deleted)", field="title")

    # Lifecycle transition enforcement
    if status is not None and status != col.get("status"):
        transitions = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
        cur = col.get("status")
        if cur not in transitions:
            _write_log(endpoint, "error", authed_user.get("id"), "VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid current collection status", field="status")
        if status not in transitions[cur]:
            _write_log(endpoint, "error", authed_user.get("id"), "INVALID_TRANSITION", {"from": cur, "to": status})
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}", from_status=cur, to_status=status)

    # No-op detection: must have effect
    changed = False
    if title is not None and title != col.get("title"):
        col["title"] = title
        changed = True
    if slug is not None and slug != col.get("slug"):
        col["slug"] = slug
        changed = True
    if status is not None and status != col.get("status"):
        col["status"] = status
        changed = True

    if not changed:
        _write_log(endpoint, "error", authed_user.get("id"), "VALIDATION_ERROR", {"rule": "no_changes"})
        return _err("VALIDATION_ERROR", "No changes to apply")

    col["updated_at"] = _now_iso()
    _save("collections.json", collections)
    _write_log(endpoint, "ok", authed_user.get("id"), None, {"collection_id": id})
    return {"collection": col}

