    user_id = bmk.get("user_id")
    authed_user = None
    if isinstance(user_id, str):
        for u in users:
            if isinstance(u, dict) and u.get("id") == user_id and u.get("status") == "active":
                authed_user = u
                break
    if not authed_user:
        _write_log(endpoint, "error", user_id if isinstance(user_id, str) else None, "UNAUTHORIZED", {"id": id})
        return _err("UNAUTHORIZED", "Not authorized to access this bookmark")

    lim = _enforce_limits(authed_user.get("id"))
    if lim:
        _write_log(endpoint, "error", authed_user.get("id"), lim["error"]["code"])
        return lim

    _write_log(endpoint, "ok", authed_user.get("id"), None, {"bookmark_id": id})
    return {"bookmark": bmk}

def update_bookmark(id, url=None, title=None, description=None, collection_id=None, tags=None, status=None, **_extra):
    import json, os, datetime, re, time, uuid, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0349000" if __import__("os").path.isdir("./environment_mix/0349000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _load_logs():
        data = _load("request_logs.json")
        return data if isinstance(data, list) else []

    def _write_log(endpoint, status_s, user_id=None, error_code=None, meta=None):
        logs = _load_logs()
        row = {
            "id": "rdp_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f") + "_" + uuid.uuid4().hex[:8],
            "service": "raindrop",
            "endpoint": endpoint,
            "user_id": user_id,
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(user_id):
        cfgs = _load("service_limits.json")
        cfgs = cfgs if isinstance(cfgs, list) else []
        cfg = None
        for r in cfgs:
            if isinstance(r, dict) and r.get("service") == "raindrop":
                cfg = r
                break
        if not isinstance(cfg, dict) or not user_id:
            return None

        window_s = cfg.get("rate_limit_window_seconds", 60)
        max_req = cfg.get("rate_limit_max_requests", None)
        daily_quota = cfg.get("daily_quota_max_requests", None)
        if not (isinstance(window_s, int) and window_s > 0):
            window_s = 60

        logs = _load_logs()
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=window_s)
        day_start = datetime.datetime(now.year, now.month, now.day)

        in_window = 0
        in_day = 0
        for row in logs:
            if not isinstance(row, dict):
                continue
            if row.get("service") != "raindrop":
                continue
            if row.get("user_id") != user_id:
                continue
            ts = row.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
            except Exception:
                continue
            if dt >= window_start:
                in_window += 1
            if dt >= day_start:
                in_day += 1

        if isinstance(max_req, int) and max_req >= 0 and in_window >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(daily_quota, int) and daily_quota >= 0 and in_day >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    endpoint = "update_bookmark"

    # Validate inputs
    if not isinstance(id, str) or not re.match(r"^rdp_bmk_01H[0-9A-Za-z]{20}$", id):
        _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "id"})
        return _err("VALIDATION_ERROR", "Invalid id format", field="id")

    if url is not None:
        if not isinstance(url, str) or not (1 <= len(url) <= 4096):
            _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "url"})
            return _err("VALIDATION_ERROR", "url must be a string of length 1..4096", field="url")
        p = urllib.parse.urlparse(url)
        if p.scheme not in ("http", "https") or not p.netloc:
            _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "url"})
            return _err("VALIDATION_ERROR", "url must be a valid http(s) URL", field="url")

    if title is not None and (not isinstance(title, str) or len(title.strip()) < 1):
        _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "title"})
        return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")
    if title is not None:
        title = title.strip()

    if description is not None and not isinstance(description, str):
        _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string", field="description")

    if collection_id is not None:
        if not isinstance(collection_id, str) or not re.match(r"^(0|rdp_col_01H[0-9A-Za-z]{20})$", collection_id):
            _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "collection_id"})
            return _err("VALIDATION_ERROR", "Invalid collection_id", field="collection_id")

    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) for x in tags):
            _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "tags"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "trashed", "deleted"):
            _write_log(endpoint, "error", None, "VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status")

    bookmarks = _load("bookmarks.json")
    bookmarks = bookmarks if isinstance(bookmarks, list) else []
    users = _load("users.json")
    users = users if isinstance(users, list) else []
    collections = _load("collections.json")
    collections = collections if isinstance(collections, list) else []
    tags_rows = _load("tags.json")
    tags_rows = tags_rows if isinstance(tags_rows, list) else []
    edges = _load("bookmark_tags.json")
    edges = edges if isinstance(edges, list) else []

    bmk = None
    for r in bookmarks:
        if isinstance(r, dict) and r.get("id") == id:
            bmk = r
            break
    if not isinstance(bmk, dict) or bmk.get("status") == "deleted":
        _write_log(endpoint, "error", None, "NOT_FOUND", {"id": id})
        return _err("NOT_FOUND", "Bookmark not found")

    # Ambient auth: bookmark owner must be active user
    user_id = bmk.get("user_id")
    authed_user = None
    if isinstance(user_id, str):
        for u in users:
            if isinstance(u, dict) and u.get("id") == user_id and u.get("status") == "active":
                authed_user = u
                break
    if not authed_user:
        _write_log(endpoint, "error", user_id if isinstance(user_id, str) else None, "UNAUTHORIZED", {"id": id})
        return _err("UNAUTHORIZED", "Not authorized to update this bookmark")

    lim = _enforce_limits(authed_user.get("id"))
    if lim:
        _write_log(endpoint, "error", authed_user.get("id"), lim["error"]["code"])
        return lim

    # Resolve target collection if moving
    target_collection = None
    if collection_id is not None:
        if collection_id == "0":
            for c in collections:
                if isinstance(c, dict) and c.get("user_id") == authed_user.get("id") and c.get("is_system") is True and c.get("slug") == "unsorted" and c.get("status") == "active":
                    target_collection = c
                    break
            if not target_collection:
                _write_log(endpoint, "error", authed_user.get("id"), "NOT_FOUND", {"field": "collection_id"})
                return _err("NOT_FOUND", "Unsorted collection not found or not active", field="collection_id")
        else:
            for c in collections:
                if isinstance(c, dict) and c.get("id") == collection_id:
                    target_collection = c
                    break
            if not isinstance(target_collection, dict) or target_collection.get("status") != "active":
                _write_log(endpoint, "error", authed_user.get("id"), "NOT_FOUND", {"field": "collection_id"})
                return _err("NOT_FOUND", "Collection not found", field="collection_id")
            if target_collection.get("user_id") != authed_user.get("id"):
                _write_log(endpoint, "error", authed_user.get("id"), "UNAUTHORIZED", {"field": "collection_id"})
                return _err("UNAUTHORIZED", "Not authorized to use this collection", field="collection_id")

    # Enforce unique(user_id,url) where status != deleted
    if url is not None and url != bmk.get("url"):
        for r in bookmarks:
            if not isinstance(r, dict):
                continue
            if r.get("user_id") != authed_user.get("id"):
                continue
            if r.get("status") == "deleted":
                continue
            if r.get("url") == url and r.get("id") != id:
                _write_log(endpoint, "error", authed_user.get("id"), "CONFLICT", {"field": "url"})
                return _err("CONFLICT", "A bookmark with this url already exists", field="url")

    # Lifecycle transitions
    if status is not None and status != bmk.get("status"):
        transitions = {"active": ["trashed", "deleted"], "trashed": ["active", "deleted"], "deleted": []}
        cur = bmk.get("status")
        if cur not in transitions:
            _write_log(endpoint, "error", authed_user.get("id"), "VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid current bookmark status", field="status")
        if status not in transitions[cur]:
            _write_log(endpoint, "error", authed_user.get("id"), "INVALID_TRANSITION", {"from": cur, "to": status})
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}", from_status=cur, to_status=status)

    # Tag normalization/upsert
    def _norm_tag(s):
        s = s.strip().casefold()
        s = re.sub(r"\s+", " ", s)
        return s

    def _new_id(prefix):
        return prefix + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f") + "_" + uuid.uuid4().hex[:6]

    changed = False

    if url is not None and url != bmk.get("url"):
        bmk["url"] = url
        try:
            bmk["domain"] = urllib.parse.urlparse(url).netloc.lower() or bmk.get("domain")
        except Exception:
            pass
        changed = True
    if title is not None and title != bmk.get("title"):
        bmk["title"] = title
        changed = True
    if description is not None and description != bmk.get("description"):
        bmk["description"] = description
        changed = True
    if target_collection is not None and target_collection.get("id") != bmk.get("collection_id"):
        # ownership integrity ensured by resolving target_collection
        bmk["collection_id"] = target_collection.get("id")
        changed = True
    if status is not None and status != bmk.get("status"):
        bmk["status"] = status
        changed = True

    # Replace tags if provided
    if tags is not None:
        normed = []
        seen = set()
        for t in tags:
            nt = _norm_tag(t)
            if not (1 <= len(nt) <= 64):
                _write_log(endpoint, "error", authed_user.get("id"), "VALIDATION_ERROR", {"field": "tags"})
                return _err("VALIDATION_ERROR", "Tag name length must be between 1 and 64 after normalization", field="tags")
            if nt in seen:
                continue
            seen.add(nt)
            normed.append(nt)

        # Map normalized names to tag rows (upsert active if missing; if merged, treat as conflict for simplicity? choose active if exists)
        name_to_tagid = {}
        for nt in normed:
            found = None
            for tr in tags_rows:
                if not isinstance(tr, dict):
                    continue
                if tr.get("user_id") != authed_user.get("id"):
                    continue
                if tr.get("status") == "deleted":
                    continue
                if tr.get("name") == nt and tr.get("status") == "active":
                    found = tr
                    break
            if not found:
                # if exists but merged, keep merged out of use by creating new active tag with same name would violate unique where status != deleted.
                # So, if merged exists, cannot reuse: treat as INVALID_TRANSITION/business rule; but store has "merged" lifecycle. Prefer to refuse.
                for tr in tags_rows:
                    if isinstance(tr, dict) and tr.get("user_id") == authed_user.get("id") and tr.get("name") == nt and tr.get("status") == "merged":
                        _write_log(endpoint, "error", authed_user.get("id"), "CONFLICT", {"field": "tags", "tag": nt})
                        return _err("CONFLICT", "Tag is merged and cannot be directly assigned", field="tags", tag=nt)
                new_tag = {
                    "id": _new_id("rdp_tag_"),
                    "user_id": authed_user.get("id"),
                    "name": nt,
                    "created_at": _now_iso(),
                    "updated_at": _now_iso(),
                    "status": "active",
                }
                tags_rows.append(new_tag)
                found = new_tag
                changed = True
            name_to_tagid[nt] = found.get("id")

        # Remove existing edges for this bookmark (replace set)
        before = len(edges)
        edges = [e for e in edges if not (isinstance(e, dict) and e.get("bookmark_id") == id)]
        if len(edges) != before:
            changed = True

        # Add new edges (ignore duplicates)
        existing_pairs = set()
        for e in edges:
            if isinstance(e, dict):
                existing_pairs.add((e.get("bookmark_id"), e.get("tag_id")))
        for nt in normed:
            tid = name_to_tagid.get(nt)
            if not tid:
                continue
            pair = (id, tid)
            if pair in existing_pairs:
                continue
            edges.append({
                "id": _new_id("rdp_btg_"),
                "bookmark_id": id,
                "tag_id": tid,
                "user_id": authed_user.get("id"),
                "created_at": _now_iso(),
            })
            existing_pairs.add(pair)
            changed = True

    if not changed:
        _write_log(endpoint, "error", authed_user.get("id"), "VALIDATION_ERROR", {"rule": "no_changes"})
        return _err("VALIDATION_ERROR", "No changes to apply")

    # created_at <= updated_at
    bmk["updated_at"] = _now_iso()
    _save("bookmarks.json", bookmarks)
    _save("tags.json", tags_rows)
    _save("bookmark_tags.json", edges)

    _write_log(endpoint, "ok", authed_user.get("id"), None, {"bookmark_id": id})
    return {"bookmark": bmk}
